import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Double> employeeSalaries = new LinkedHashMap<>();
        double totalBudget = 0;

        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line = br.readLine(); // skip header
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(",");
            String name = parts[1].trim();
            String department = parts[2].trim();
            double salary = Double.parseDouble(parts[3].trim());

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            employeeSalaries.put(name, salary);
            totalBudget += salary;
        }
        br.close();

        String highestName = "";
        double highestSalary = Double.NEGATIVE_INFINITY;
        for (Map.Entry<String, Double> entry : employeeSalaries.entrySet()) {
            if (entry.getValue() > highestSalary) {
                highestSalary = entry.getValue();
                highestName = entry.getKey();
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            double avg = entry.getValue().stream().mapToDouble(Double::doubleValue).average().orElse(0);
            sb.append(String.format("  %s: $%,.2f\n", entry.getKey(), avg));
        }
        sb.append("\n");
        sb.append(String.format("Highest Paid: %s ($%,.0f)\n", highestName, highestSalary));
        sb.append("\n");
        sb.append("Departments with >2 employees:\n");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            if (entry.getValue().size() > 2) {
                sb.append(String.format("  %s (%d employees)\n", entry.getKey(), entry.getValue().size()));
            }
        }
        sb.append("\n");
        sb.append(String.format("Total Budget: $%,.0f\n", totalBudget));

        System.out.print(sb.toString());
    }
}

