let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [Int: Int] = [:]

for line in lines {
    guard let bracketEnd = line.firstIndex(of: "]") else { continue }
    let timestamp = line[line.index(line.startIndex, offsetBy: 1)..<bracketEnd]
    let rest = line[line.index(after: bracketEnd)...]
    let restStr = String(rest)

    guard let dashSpace = restStr.range(of: " - ") else { continue }
    let beforeDash = String(restStr[restStr.startIndex..<dashSpace.lowerBound])
    let message = String(restStr[dashSpace.upperBound...])

    guard let parenStart = beforeDash.firstIndex(of: "(") else { continue }
    let level = String(beforeDash[beforeDash.startIndex..<parenStart]).trimmingCharacters(in: .whitespaces)
    let component = String(beforeDash[parenStart...]).trimmingCharacters(in: CharacterSet(charactersIn: "()"))

    let tsStr = String(timestamp)
    let hourStr = String(tsStr[tsStr.index(tsStr.startIndex, offsetBy: 11)..<tsStr.index(tsStr.startIndex, offsetBy: 13)])
    let hour = Int(hourStr) ?? 0

    levelCounts[level, default: 0] += 1
    hourCounts[hour, default: 0] += 1

    if level == "ERROR" {
        errorComponentCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

