import * as fs from 'fs';

const logPath = '<tmp>';
const content: string = fs.readFileSync(logPath, 'utf-8');
const lines: string[] = content.split('\n').filter(line => line.trim() !== '');

interface LogEntry {
  hour: string;
  level: string;
  component: string;
  message: string;
}

const entries: LogEntry[] = [];
const regex = /^\[(\d{4}-\d{2}-\d{2}) (\d{2}):\d{2}:\d{2}\] (\S+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
  const match = line.match(regex);
  if (match) {
    entries.push({
      hour: match[2],
      level: match[3],
      component: match[4],
      message: match[5]
    });
  }
}

const levelCounts: Map<string, number> = new Map();
for (const e of entries) {
  levelCounts.set(e.level, (levelCounts.get(e.level) || 0) + 1);
}
const sortedLevels: [string, number][] = Array.from(levelCounts.entries()).sort((a, b) => a[0].localeCompare(b[0]));

const errorByComponent: Map<string, number> = new Map();
for (const e of entries) {
  if (e.level === 'ERROR') {
    errorByComponent.set(e.component, (errorByComponent.get(e.component) || 0) + 1);
  }
}
let maxErrorComponent = '';
let maxErrorCount = 0;
for (const [comp, count] of errorByComponent) {
  if (count > maxErrorCount || (count === maxErrorCount && comp < maxErrorComponent)) {
    maxErrorCount = count;
    maxErrorComponent = comp;
  }
}

const errorMessages: Set<string> = new Set();
for (const e of entries) {
  if (e.level === 'ERROR') {
