    for (int i = len - 1; i >= 0; i--) {
        if (count > 0 && count % 3 == 0) buf[pos++] = ',';
        buf[pos++] = tmp[i];
        count++;
    }
    buf[pos] = '\0';
    int start = 0;
    if (n < 0) start = 1;
    for (int i = start; i < (pos - start) / 2 + start; i++) {
        char t = buf[i];
        buf[i] = buf[pos - 1 - (i - start)];
        buf[pos - 1 - (i - start)] = t;
    }
}

