import * as http from 'http';

interface Product {
    id: number;
    name: string;
    price: number;
    category: string;
    stock: number;
}

function main(): void {
    const req = http.get('http://127.0.0.1:18923/api/products', (res: http.IncomingMessage) => {
        let data = '';
        res.on('data', (chunk: Buffer) => {
            data += chunk.toString();
        });
        res.on('end', () => {
            const products: Product[] = JSON.parse(data);
            const filtered = products.filter((p: Product) => p.price > 50.00);
            filtered.sort((a: Product, b: Product) => a.name.localeCompare(b.name));

            const lines: string[] = [];
            lines.push('=== Filtered Products (price > $50.00) ===');
            lines.push('');
            for (const p of filtered) {
                lines.push(`${p.name}: $${p.price.toFixed(2)}`);
            }
            lines.push('');
            lines.push(`Count: ${filtered.length}`);
            const total = filtered.reduce((sum: number, p: Product) => sum + p.price, 0);
            lines.push(`Total: $${total.toFixed(2)}`);

            process.stdout.write(lines.join('\n') + '\n');
        });
    });

    req.on('error', (err: Error) => {
        process.stderr.write(err.message + '\n');
        process.exit(1);
    });
}

main();

