use std::fs;
use std::collections::HashMap;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut error_component_counts: HashMap<String, usize> = HashMap::new();
    let mut error_messages: Vec<String> = Vec::new();
    let mut hour_counts: HashMap<u32, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let close_bracket = line.find(']').expect("No closing bracket");
        let timestamp = &line[1..close_bracket];

        let rest = &line[close_bracket + 2..];

        let open_paren = rest.find('(').expect("No open paren");
        let level = rest[..open_paren].trim().to_string();

        let close_paren = rest.find(')').expect("No close paren");
        let component = rest[open_paren + 1..close_paren].to_string();

        let after_paren = &rest[close_paren + 1..];
        let message = after_paren.trim_start_matches(" - ").to_string();

        let hour_str = &timestamp[11..13];
        let hour: u32 = hour_str.parse().expect("Invalid hour");

        *level_counts.entry(level.clone()).or_insert(0) += 1;
        *hour_counts.entry(hour).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component).or_insert(0) += 1;
            error_messages.push(message);
        }
    }

    println!("=== Log Analysis ===");
    println!();

    println!("Entries by Level:");
    let mut levels: Vec<&String> = level_counts.keys().collect();
    levels.sort();
    for level in levels {
        println!("  {}: {}", level, level_counts[level]);
    }
    println!();

    let (top_component, top_count) = error_component_counts
        .iter()
        .max_by_key(|(_, count)| count)
        .expect("No errors found");
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    let mut unique_messages: Vec<&String> = error_messages.iter().collect();
    unique_messages.sort();
    unique_messages.dedup();
    for msg in unique_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, count)| count)
        .expect("No entries found");
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

