import java.io.*;
import java.util.*;
import java.nio.file.*;

public class Main {
    private static String json;
    private static int pos;

    public static void main(String[] args) throws Exception {
        String a = new String(Files.readAllBytes(Paths.get("<tmp>")));
        String b = new String(Files.readAllBytes(Paths.get("<tmp>")));

        Object objA = parse(a);
        Object objB = parse(b);

        Object merged = deepMerge(objA, objB);

        System.out.print(prettyPrint(merged, 0));
    }

    private static Object parse(String s) {
        json = s;
        pos = 0;
        return parseValue();
    }

    private static void skipWhitespace() {
        while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
    }

    private static Object parseValue() {
        skipWhitespace();
        char c = json.charAt(pos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        if (c == 't') { pos += 4; return Boolean.TRUE; }
        if (c == 'f') { pos += 5; return Boolean.FALSE; }
        if (c == 'n') { pos += 4; return null; }
        return parseNumber();
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++; // skip {
        skipWhitespace();
        if (json.charAt(pos) == '}') { pos++; return map; }
        while (true) {
            skipWhitespace();
            String key = parseString();
            skipWhitespace();
            pos++; // skip :
            Object value = parseValue();
            map.put(key, value);
            skipWhitespace();
            if (json.charAt(pos) == ',') { pos++; continue; }
            if (json.charAt(pos) == '}') { pos++; break; }
        }
        return map;
    }

    private static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        pos++; // skip [
        skipWhitespace();
        if (json.charAt(pos) == ']') { pos++; return list; }
        while (true) {
            Object value = parseValue();
            list.add(value);
            skipWhitespace();
            if (json.charAt(pos) == ',') { pos++; continue; }
            if (json.charAt(pos) == ']') { pos++; break; }
        }
        return list;
