        String json = sb.toString();

        // Parse nodes
        List<String> nodes = new ArrayList<>();
        int nodesKey = json.indexOf("\"nodes\"");
        int bracketStart = json.indexOf('[', nodesKey);
        int bracketEnd = json.indexOf(']', bracketStart);
        String nodesStr = json.substring(bracketStart + 1, bracketEnd);
        String[] nodeParts = nodesStr.split(",");
        for (String part : nodeParts) {
            String node = part.trim().replace("\"", "");
            if (!node.isEmpty()) {
                nodes.add(node);
            }
        }

        // Parse edges
        List<int[]> edges = new ArrayList<>();
        int edgesKey = json.indexOf("\"edges\"");
        int edgesBracketStart = json.indexOf('[', edgesKey);
        int depth = 0;
        int edgesBracketEnd = -1;
        for (int i = edgesBracketStart; i < json.length(); i++) {
            char c = json.charAt(i);
            if (c == '[') depth++;
            if (c == ']') {
                depth--;
                if (depth == 0) {
                    edgesBracketEnd = i;
                    break;
                }
            }
        }
        String edgesStr = json.substring(edgesBracketStart + 1, edgesBracketEnd);

        int pos = 0;
        while (pos < edgesStr.length()) {
            int objStart = edgesStr.indexOf('{', pos);
            if (objStart == -1) break;
            int objEnd = edgesStr.indexOf('}', objStart);
            String obj = edgesStr.substring(objStart, objEnd + 1);

            int fromIdx = obj.indexOf("\"from\"");
            int fromColon = obj.indexOf(':', fromIdx);
            int fromQuote1 = obj.indexOf('"', fromColon + 1);
            int fromQuote2 = obj.indexOf('"', fromQuote1 + 1);
            String from = obj.substring(fromQuote1 + 1, fromQuote2);

            int toIdx = obj.indexOf("\"to\"");
            int toColon = obj.indexOf(':', toIdx);
            int toQuote1 = obj.indexOf('"', toColon + 1);
            int toQuote2 = obj.indexOf('"', toQuote1 + 1);
            String to = obj.substring(toQuote1 + 1, toQuote2);

            int weightIdx = obj.indexOf("\"weight\"");
            int weightColon = obj.indexOf(':', weightIdx);
            int ws = weightColon + 1;
            while (ws < obj.length() && obj.charAt(ws) == ' ') ws++;
            int we = ws;
            while (we < obj.length() && (Character.isDigit(obj.charAt(we)) || obj.charAt(we) == '-' || obj.charAt(we) == '.')) we++;
            double weight = Double.parseDouble(obj.substring(ws, we));

            int fromIdx2 = nodes.indexOf(from);
            int toIdx2 = nodes.indexOf(to);
            edges.add(new int[]{fromIdx2, toIdx2, (int) weight});

            pos = objEnd + 1;
        }

        // Build adjacency list
        int n = nodes.size();
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());

        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }

        // Dijkstra's algorithm
        Map<String, Integer> nodeToIdx = new HashMap<>();
        for (int i = 0; i < n; i++) nodeToIdx.put(nodes.get(i), i);

        int sourceIdx = nodeToIdx.get("A");
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[sourceIdx] = 0;

        boolean[] visited = new boolean[n];
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[1], b[1]));
        pq.offer(new long[]{sourceIdx, 0});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int u = (int) cur[0];
            long d = cur[1];
            if (visited[u]) continue;
            visited[u] = true;
            for (int[] neighbor : adj.get(u)) {
                int v = neighbor[0];
                int w = neighbor[1];
                if (d + w < dist[v]) {
                    dist[v] = d + w;
                    pq.offer(new long[]{v, d + w});
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        List<String> sortedNodes = new ArrayList<>(nodes);
        Collections.sort(sortedNodes);
        for (String node : sortedNodes) {
            int idx = nodeToIdx.get(node);
            System.out.println("A -> " + node + ": " + dist[idx]);
        }
    }
