import java.io.ByteArrayOutputStream;

public class Main {
    public static void main(String[] args) throws Exception {
        String hostname = runCommand("hostname");
        String os = runCommand("uname -s");
        String architecture = runCommand("uname -m");
        String username = runCommand("whoami");

        StringBuilder sb = new StringBuilder();
        sb.append("{\n");
        sb.append("  \"hostname\": \"").append(escapeJson(hostname)).append("\",\n");
        sb.append("  \"os\": \"").append(escapeJson(os)).append("\",\n");
        sb.append("  \"architecture\": \"").append(escapeJson(architecture)).append("\",\n");
        sb.append("  \"username\": \"").append(escapeJson(username)).append("\"");
        sb.append("\n}");

        System.out.print(sb.toString());
    }

    private static String runCommand(String command) throws Exception {
        String[] cmd = command.split("\\s+");
        Process process = new ProcessBuilder(cmd).redirectErrorStream(true).start();
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buffer = new byte[1024];
        int len;
        while ((len = process.getInputStream().read(buffer)) != -1) {
            baos.write(buffer, 0, len);
        }
        process.waitFor();
        return baos.toString("UTF-8").trim();
    }

    private static String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}

