use std::fs;
use std::collections::HashMap;

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        let got = self.next();
        assert_eq!(got, Some(c), "Expected '{}' at position {}", c, self.pos);
    }

    fn parse_string(&mut self) -> String {
        self.skip_whitespace();
        self.expect('"');
        let mut s = String::new();
        loop {
            let c = self.next().unwrap();
            if c == '"' {
                break;
            }
            if c == '\\' {
                let esc = self.next().unwrap();
                match esc {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'n' => s.push('\n'),
                    't' => s.push('\t'),
                    'r' => s.push('\r'),
                    'b' => s.push('\u{0008}'),
                    'f' => s.push('\u{000C}'),
                    _ => s.push(esc),
                }
            } else {
                s.push(c);
            }
        }
        s
    }

    fn parse_number(&mut self) -> f64 {
        self.skip_whitespace();
        let mut s = String::new();
        if self.peek() == Some('-') {
            s.push('-');
            self.next();
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
                s.push(c);
                self.next();
            } else {
                break;
            }
        }
        s.parse::<f64>().unwrap()
    }

    fn parse_value(&mut self) -> Value {
        self.skip_whitespace();
        match self.peek() {
            Some('"') => Value::Str(self.parse_string()),
            Some('{') => {
                self.next();
                let mut map = HashMap::new();
                self.skip_whitespace();
                if self.peek() == Some('}') {
                    self.next();
                    return Value::Obj(map);
                }
                loop {
                    self.skip_whitespace();
                    let key = self.parse_string();
                    self.skip_whitespace();
                    self.expect(':');
                    let val = self.parse_value();
                    map.insert(key, val);
                    self.skip_whitespace();
                    match self.next() {
                        Some(',') => continue,
                        Some('}') => break,
                        _ => panic!("Expected ',' or '}'"),
                    }
                }
                Value::Obj(map)
            }
            Some('[') => {
                self.next();
                let mut arr = Vec::new();
                self.skip_whitespace();
                if self.peek() == Some(']') {
                    self.next();
                    return Value::Arr(arr);
                }
                loop {
                    let val = self.parse_value();
                    arr.push(val);
                    self.skip_whitespace();
                    match self.next() {
                        Some(',') => continue,
                        Some(']') => break,
                        _ => panic!("Expected ',' or ']'"),
                    }
                }
                Value::Arr(arr)
            }
            Some('t') => {
                self.next(); self.next(); self.next(); self.next();
                Value::Bool(true)
            }
            Some('f') => {
                self.next(); self.next(); self.next(); self.next(); self.next();
                Value::Bool(false)
            }
            Some('n') => {
                self.next(); self.next(); self.next(); self.next();
                Value::Null
            }
            _ => Value::Num(self.parse_number()),
        }
    }
}

enum Value {
    Str(String),
    Num(f64),
    Bool(bool),
    Null,
    Arr(Vec<Value>),
    Obj(HashMap<String, Value>),
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let mut parser = Parser::new(&content);
    let root = parser.parse_value();

    let root = match root {
        Value::Obj(m) => m,
        _ => panic!("Expected object"),
    };

    let nodes_val = root.get("nodes").expect("Missing 'nodes'");
    let edges_val = root.get("edges").expect("Missing 'edges'");

    let nodes: Vec<String> = match nodes_val {
        Value::Arr(arr) => arr.iter().map(|v| match v {
            Value::Str(s) => s.clone(),
            _ => panic!("Expected string in nodes"),
        }).collect(),
        _ => panic!("Expected array for nodes"),
    };

    let edges: Vec<(String, String, f64)> = match edges_val {
        Value::Arr(arr) => arr.iter().map(|v| {
            let obj = match v {
                Value::Obj(m) => m,
                _ => panic!("Expected object in edges"),
            };
            let from = match obj.get("from").unwrap() {
                Value::Str(s) => s.clone(),
                _ => panic!("Expected string for 'from'"),
            };
            let to = match obj.get("to").unwrap() {
                Value::Str(s) => s.clone(),
                _ => panic!("Expected string for 'to'"),
            };
            let weight = match obj.get("weight").unwrap() {
                Value::Num(n) => *n,
                _ => panic!("Expected number for 'weight'"),
            };
            (from, to, weight)
        }).collect(),
        _ => panic!("Expected array for edges"),
    };

    // Build adjacency list (undirected)
    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), *weight));
        adj.entry(to.clone()).or_insert_with(Vec::new).push((from.clone(), *weight));
    }

    // Dijkstra's algorithm from "A"
    let mut dist: HashMap<String, f64> = HashMap::new();
    let mut visited: HashMap<String, bool> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), f64::INFINITY);
        visited.insert(node.clone(), false);
    }
    dist.insert("A".to_string(), 0.0);

    for _ in 0..nodes.len() {
        // Find unvisited node with minimum distance
        let mut min_node: Option<&String> = None;
        let mut min_dist = f64::INFINITY;
        for node in &nodes {
            if !visited[node] && dist[node] < min_dist {
                min_dist = dist[node];
                min_node = Some(node);
            }
        }

        let min_node = match min_node {
            Some(n) => n.clone(),
            None => break,
        };

        if visited[&min_node] {
            continue;
        }
        visited.insert(min_node.clone(), true);

        // Relax edges
        if let Some(neighbors) = adj.get(&min_node) {
            for (neighbor, weight) in neighbors {
                let new_dist = dist[&min_node] + weight;
                if new_dist < dist[neighbor] {
                    dist.insert(neighbor.clone(), new_dist);
                }
            }
        }
    }

    // Output
    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    for node in sorted_nodes {
        let d = dist[node];
        if d == f64::INFINITY {
            println!("A -> {}: unreachable", node);
        } else if d == d.floor() {
            println!("A -> {}: {}", node, d as i64);
        } else {
            println!("A -> {}: {}", node, d);
        }
    }
}

