import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileEntry {
  relativePath: string;
  lines: number;
  chars: number;
}

function getExtension(basename: string): string {
  const lastDot = basename.lastIndexOf('.');
  if (lastDot <= 0) return '';
  return basename.substring(lastDot);
}

function countLines(text: string): number {
  if (text.length === 0) return 0;
  let newlines = 0;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '\n') newlines++;
  }
  return newlines + (text.endsWith('\n') ? 0 : 1);
}

function walkDir(dir: string, root: string): FileEntry[] {
  const results: FileEntry[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) continue;

    if (entry.isDirectory()) {
      results.push(...walkDir(fullPath, root));
    } else if (entry.isFile()) {
      const content = fs.readFileSync(fullPath);
      const chars = content.length;
      const text = content.toString('utf-8');
      const lines = countLines(text);
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      results.push({ relativePath, lines, chars });
    }
  }

  return results;
}

const allFiles = walkDir(rootDir, rootDir);

const groups: Map<string, FileEntry[]> = new Map();

for (const file of allFiles) {
  const basename = path.basename(file.relativePath);
  const ext = getExtension(basename);
  if (!groups.has(ext)) {
    groups.set(ext, []);
  }
  groups.get(ext)!.push(file);
}

const sortedExts = Array.from(groups.keys()).sort();

for (const ext of sortedExts) {
  groups.get(ext)!.sort((a, b) => a.relativePath < b.relativePath ? -1 : a.relativePath > b.relativePath ? 1 : 0);
}

let output = '=== File Tree Analysis ===\n\n';

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of sortedExts) {
  const files = groups.get(ext)!;
  const extFiles = files.length;
  const extLines = files.reduce((sum, f) => sum + f.lines, 0);
  const extChars = files.reduce((sum, f) => sum + f.chars, 0);

  totalFiles += extFiles;
  totalLines += extLines;
  totalChars += extChars;

  output += `Extension: ${ext}\n`;
  output += `  Files: ${extFiles}\n`;
  output += `  Total Lines: ${extLines}\n`;
  output += `  Total Characters: ${extChars}\n`;

  for (const file of files) {
    output += `    ${file.relativePath}: ${file.lines} lines, ${file.chars} chars\n`;
  }
}

output += '\n';
output += `Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`;

process.stdout.write(output);

