    } else {
        /* Use %g but ensure at least one decimal place for non-integers */
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", n);
        /* Check if it looks like an integer (no . or e) */
        int has_dot = 0, has_e = 0;
        for (char *p = buf; *p; p++) {
