static JsonValue *parse_object(Parser *p) {
    p->pos++; /* { */
    JsonValue *obj = json_new_object();
    skip_ws(p);
    if (p->pos < p->len && p->text[p->pos] == '}') {
        p->pos++;
        return obj;
    }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        skip_ws(p);
        if (p->pos >= p->len || p->text[p->pos] != ':') {
            fprintf(stderr, "Expected : at pos %d\n", p->pos);
            exit(1);
        }
        p->pos++;
        skip_ws(p);
        JsonValue *val = parse_value(p);
        object_add(obj, key, val);
        free(key);
        skip_ws(p);
        if (p->pos < p->len && p->text[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->text[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            fprintf(stderr, "Expected , or } in object at pos %d\n", p->pos);
            exit(1);
        }
    }
    return obj;
}

static JsonValue *parse_value(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) { fprintf(stderr, "Unexpected end of input\n"); exit(1); }
    char c = p->text[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') return parse_string(p);
    if (c == 't') {
        if (p->pos + 4 <= p->len && strncmp(p->text + p->pos, "true", 4) == 0) {
            p->pos += 4;
            return json_new_bool(1);
        }
        fprintf(stderr, "Invalid token at pos %d\n", p->pos);
        exit(1);
    }
    if (c == 'f') {
        if (p->pos + 5 <= p->len && strncmp(p->text + p->pos, "false", 5) == 0) {
            p->pos += 5;
            return json_new_bool(0);
        }
        fprintf(stderr, "Invalid token at pos %d\n", p->pos);
        exit(1);
    }
    if (c == 'n') {
        if (p->pos + 4 <= p->len && strncmp(p->text + p->pos, "null", 4) == 0) {
            p->pos += 4;
            return json_new_null();
        }
        fprintf(stderr, "Invalid token at pos %d\n", p->pos);
        exit(1);
    }
    if (c == '-' || (c >= '0' && c <= '9')) {
        return parse_number(p);
    }
    fprintf(stderr, "Unexpected char '%c' at pos %d\n", c, p->pos);
    exit(1);
}

static JsonValue *deep_copy(JsonValue *v) {
    if (!v) return NULL;
    switch (v->type) {
        case JSON_NULL:
            return json_new_null();
        case JSON_BOOL:
            return json_new_bool(v->boolean);
        case JSON_NUMBER:
            return json_new_number(v->number);
        case JSON_STRING:
            return json_new_string(v->string);
        case JSON_ARRAY: {
            JsonValue *a = json_new_array();
            for (int i = 0; i < v->array.count; i++)
                array_push(a, deep_copy(v->array.items[i]));
            return a;
        }
        case JSON_OBJECT: {
            JsonValue *o = json_new_object();
            for (int i = 0; i < v->object.count; i++)
                object_add(o, v->object.pairs[i].key, deep_copy(v->object.pairs[i].value));
            return o;
        }
    }
    return NULL;
}

static int json_equal(JsonValue *a, JsonValue *b) {
    if (!a || !b) return a == b;
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->boolean == b->boolean;
        case JSON_NUMBER: return a->number == b->number;
        case JSON_STRING: return strcmp(a->string, b->string) == 0;
        case JSON_ARRAY:
            if (a->array.count != b->array.count) return 0;
            for (int i = 0; i < a->array.count; i++)
                if (!json_equal(a->array.items[i], b->array.items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->object.count != b->object.count) return 0;
            for (int i = 0; i < a->object.count; i++) {
                JsonValue *bv = object_get(b, a->object.pairs[i].key);
                if (!bv) return 0;
                if (!json_equal(a->object.pairs[i].value, bv)) return 0;
            }
            return 1;
    }
    return 0;
}

static int array_contains(JsonValue *arr, JsonValue *item) {
    for (int i = 0; i < arr->array.count; i++) {
        if (json_equal(arr->array.items[i], item))
            return 1;
    }
    return 0;
}

static JsonValue *deep_merge(JsonValue *a, JsonValue *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = json_new_object();
        /* Add all keys from A, merging with B if present */
        for (int i = 0; i < a->object.count; i++) {
            const char *key = a->object.pairs[i].key;
            JsonValue *bv = object_get(b, key);
            if (bv) {
                object_add(result, key, deep_merge(a->object.pairs[i].value, bv));
            } else {
                object_add(result, key, deep_copy(a->object.pairs[i].value));
            }
        }
        /* Add keys only in B */
        for (int i = 0; i < b->object.count; i++) {
            const char *key = b->object.pairs[i].key;
            if (!object_get(a, key)) {
                object_add(result, key, deep_copy(b->object.pairs[i].value));
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = json_new_array();
        for (int i = 0; i < a->array.count; i++)
            array_push(result, deep_copy(a->array.items[i]));
        for (int i = 0; i < b->array.count; i++) {
            if (!array_contains(result, b->array.items[i]))
                array_push(result, deep_copy(b->array.items[i]));
        }
        return result;
    }
    /* Scalar conflict or type mismatch: B overrides A */
    return deep_copy(b);
}

static void print_string_escaped(const char *s) {
    fputc('"', stdout);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", stdout); break;
            case '\\': fputs("\\\\", stdout); break;
            case '\b': fputs("\\b", stdout); break;
            case '\f': fputs("\\f", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default:
                if (c < 0x20)
                    fprintf(stdout, "\\u%04x", c);
                else
                    fputc(c, stdout);
        }
    }
    fputc('"', stdout);
}

static void print_number(double n) {
    if (n == (double)(long long)n && fabs(n) < 1e15) {
        fprintf(stdout, "%lld", (long long)n);
    } else {
        /* Use %g but ensure at least one decimal place for non-integers */
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", n);
        /* Check if it looks like an integer (no . or e) */
        int has_dot = 0, has_e = 0;
        for (char *p = buf; *p; p++) {
            if (*p == '.') has_dot = 1;
            if (*p == 'e' || *p == 'E') has_e = 1;
        }
        if (!has_dot && !has_e) {
            fprintf(stdout, "%s.0", buf);
        } else {
            fprintf(stdout, "%s", buf);
        }
    }
}

static void print_json(JsonValue *v, int indent, int depth) {
    int i;
    switch (v->type) {
        case JSON_NULL:
            fprintf(stdout, "null");
            break;
        case JSON_BOOL:
            fprintf(stdout, v->boolean ? "true" : "false");
            break;
        case JSON_NUMBER:
            print_number(v->number);
            break;
        case JSON_STRING:
            print_string_escaped(v->string);
            break;
        case JSON_ARRAY:
            if (v->array.count == 0) {
                fprintf(stdout, "[]");
                break;
            }
            fprintf(stdout, "[\n");
            for (i = 0; i < v->array.count; i++) {
                for (int j = 0; j < (depth + 1) * indent; j++) fputc(' ', stdout);
                print_json(v->array.items[i], indent, depth + 1);
                if (i < v->array.count - 1) fputc(',', stdout);
                fputc('\n', stdout);
            }
            for (int j = 0; j < depth * indent; j++) fputc(' ', stdout);
            fputc(']', stdout);
            break;
        case JSON_OBJECT:
            if (v->object.count == 0) {
                fprintf(stdout, "{}");
                break;
            }
            /* Sort keys alphabetically */
            int n = v->object.count;
            const char **keys = xmalloc(n * sizeof(char*));
            for (i = 0; i < n; i++)
                keys[i] = v->object.pairs[i].key;

            /* Simple insertion sort for keys */
            for (i = 1; i < n; i++) {
                const char *tmp = keys[i];
                int j = i - 1;
                while (j >= 0 && strcmp(keys[j], tmp) > 0) {
                    keys[j + 1] = keys[j];
                    j--;
                }
                keys[j + 1] = tmp;
            }

            fprintf(stdout, "{\n");
            for (i = 0; i < n; i++) {
                for (int j = 0; j < (depth + 1) * indent; j++) fputc(' ', stdout);
                print_string_escaped(keys[i]);
                fprintf(stdout, ": ");
                /* Find the value for this key */
                JsonValue *val = NULL;
                for (int k = 0; k < v->object.count; k++) {
                    if (strcmp(v->object.pairs[k].key, keys[i]) == 0) {
                        val = v->object.pairs[k].value;
                        break;
                    }
                }
                print_json(val, indent, depth + 1);
                if (i < n - 1) fputc(',', stdout);
                fputc('\n', stdout);
            }
            for (int j = 0; j < depth * indent; j++) fputc(' ', stdout);
            fputc('}', stdout);
            free(keys);
            break;
    }
}

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = xmalloc((size_t)sz + 1);
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    fclose(f);
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    char *text_a = read_file(path_a);
    char *text_b = read_file(path_b);

    Parser pa = { text_a, 0, (int)strlen(text_a) };
    Parser pb = { text_b, 0, (int)strlen(text_b) };

    JsonValue *a = parse_value(&pa);
    JsonValue *b = parse_value(&pb);

    JsonValue *merged = deep_merge(a, b);

    print_json(merged, 2, 0);
    fputc('\n', stdout);

    return 0;
}
