use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(BTreeMap<String, Json>),
}

impl PartialEq for Json {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Json::Null, Json::Null) => true,
            (Json::Bool(a), Json::Bool(b)) => a == b,
            (Json::Number(a), Json::Number(b)) => a == b,
            (Json::String(a), Json::String(b)) => a == b,
            (Json::Array(a), Json::Array(b)) => a == b,
            (Json::Object(a), Json::Object(b)) => a == b,
            _ => false,
        }
    }
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(input: &str) -> Self {
        Parser {
            chars: input.chars().collect(),
            pos: 0,
        }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next_char(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) {
        assert_eq!(self.next_char(), Some(c), "expected '{}'", c);
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => {
                self.parse_literal("true");
                Json::Bool(true)
            }
            Some('f') => {
                self.parse_literal("false");
                Json::Bool(false)
            }
            Some('n') => {
                self.parse_literal("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_literal(&mut self, literal: &str) {
        for c in literal.chars() {
            assert_eq!(self.next_char(), Some(c));
        }
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        let n: f64 = s.parse().unwrap();
        Json::Number(n)
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut result = String::new();
        loop {
            let c = self.next_char().unwrap();
            match c {
                '"' => break,
                '\\' => {
                    let esc = self.next_char().unwrap();
                    match esc {
                        '"' => result.push('"'),
                        '\\' => result.push('\\'),
                        '/' => result.push('/'),
                        'b' => result.push('\u{0008}'),
                        'f' => result.push('\u{000C}'),
                        'n' => result.push('\n'),
                        'r' => result.push('\r'),
                        't' => result.push('\t'),
                        'u' => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                let h = self.next_char().unwrap();
                                code = code * 16 + (h.to_digit(16).unwrap() as u32);
                            }
                            if code >= 0xD800 && code <= 0xDBFF {
                                if self.peek() == Some('\\') {
                                    self.pos += 1;
                                    if self.peek() == Some('u') {
                                        self.pos += 1;
                                        let mut low = 0u32;
                                        for _ in 0..4 {
                                            let h = self.next_char().unwrap();
                                            low = low * 16 + (h.to_digit(16).unwrap() as u32);
                                        }
                                        let cp =
                                            0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                        result.push(char::from_u32(cp).unwrap());
                                    }
                                }
                            } else {
                                result.push(char::from_u32(code).unwrap());
                            }
                        }
                        _ => unreachable!(),
                    }
                }
                _ => result.push(c),
            }
        }
        result
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.pos += 1;
            return Json::Array(items);
        }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some(']') => break,
                _ => unreachable!(),
            }
        }
        Json::Array(items)
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.pos += 1;
            return Json::Object(map);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.expect(':');
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some('}') => break,
                _ => unreachable!(),
            }
        }
        Json::Object(map)
    }
}

fn deep_merge(a: Json, b: Json) -> Json {
    match (&a, &b) {
        (Json::Object(a_map), Json::Object(b_map)) => {
            let mut merged = a_map.clone();
            for (key, b_val) in b_map {
                match merged.get(key) {
                    Some(a_val) => {
                        merged.insert(key.clone(), deep_merge(a_val.clone(), b_val.clone()));
                    }
                    None => {
                        merged.insert(key.clone(), b_val.clone());
                    }
                }
            }
            Json::Object(merged)
        }
        (Json::Array(a_arr), Json::Array(b_arr)) => {
            let mut merged = a_arr.clone();
            for item in b_arr {
                if !merged.iter().any(|x| x == item) {
                    merged.push(item.clone());
                }
            }
            Json::Array(merged)
        }
        _ => b,
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn pretty_print(json: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match json {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => format!("{}", n),
        Json::String(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                "[]".to_string()
            } else {
                let mut parts = Vec::new();
                for item in arr {
                    parts.push(format!(
                        "{}{}",
                        pad_inner,
                        pretty_print(item, indent + 1)
                    ));
                }
                format!("[\n{}\n{}]", parts.join(",\n"), pad)
            }
        }
        Json::Object(map) => {
            if map.is_empty() {
                "{}".to_string()
            } else {
                let mut parts = Vec::new();
                for (key, val) in map {
                    parts.push(format!(
                        "{}\"{}\": {}",
                        pad_inner,
                        escape_string(key),
                        pretty_print(val, indent + 1)
                    ));
                }
                format!("{{\n{}\n{}}}", parts.join(",\n"), pad)
            }
        }
    }
}

fn main() {
    let path_a =
        "<tmp>";
    let path_b =
        "<tmp>";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let json_a = Parser::new(&content_a).parse_value();
    let json_b = Parser::new(&content_b).parse_value();

    let merged = deep_merge(json_a, json_b);

    println!("{}", pretty_print(&merged, 0));
}
