                } else {
                    file_name[pos..].to_string()
                }
            } else {
                "(no extension)".to_string()
            };

            let rel = path.strip_prefix(root).unwrap();
            let rel_str = rel.to_string_lossy().to_string();

            groups.entry(ext).or_default().push((rel_str, lines, chars));

            *total_files += 1;
            *total_lines += lines;
            *total_chars += chars;
        }
    }
