#include <string.h>

#define MAX_LINE 8192
#define MAX_ENTRIES 100000
#define MAX_STR 1024

typedef struct {
    char level[MAX_STR];
    char component[MAX_STR];
    char message[MAX_STR];
    int hour;
} LogEntry;

char *my_strdup(const char *s) {
    size_t len = strlen(s) + 1;
    char *p = malloc(len);
    if (p) memcpy(p, s, len);
    return p;
}

int main(void) {
    const char *filepath = "<tmp>";

    FILE *fp = fopen(filepath, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open file\n");
        return 1;
    }

    LogEntry *entries = malloc((size_t)MAX_ENTRIES * sizeof(LogEntry));
    if (!entries) {
        fprintf(stderr, "Error: malloc failed\n");
        fclose(fp);
        return 1;
    }

    int count = 0;
    char line[MAX_LINE];

    while (fgets(line, sizeof(line), fp) && count < MAX_ENTRIES) {
        size_t len = strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            line[--len] = '\0';
        }
        if (len == 0) continue;

        char *p = line;
        if (*p != '[') continue;
        p++;

        char *close_bracket = strchr(p, ']');
        if (!close_bracket) continue;

        int hour = 0;
        if (close_bracket - p >= 13) {
            hour = (p[11] - '0') * 10 + (p[12] - '0');
        }

        p = close_bracket + 1;
        while (*p == ' ') p++;

        char level[MAX_STR] = "";
        int i = 0;
        while (*p && *p != ' ' && i < MAX_STR - 1) {
            level[i++] = *p++;
        }
        level[i] = '\0';

        while (*p == ' ') p++;

        char component[MAX_STR] = "";
        if (*p == '(') {
            p++;
            i = 0;
            while (*p && *p != ')' && i < MAX_STR - 1) {
                component[i++] = *p++;
            }
            component[i] = '\0';
            if (*p == ')') p++;
        }

        while (*p == ' ') p++;
        if (*p == '-') {
            p++;
            while (*p == ' ') p++;
        }

        char message[MAX_STR] = "";
        i = 0;
        while (*p && i < MAX_STR - 1) {
            message[i++] = *p++;
        }
        message[i] = '\0';

