        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            line[--len] = '\0';
        }
        if (len == 0) continue;

        char *p = line;
        if (*p != '[') continue;
        p++;

        char *close_bracket = strchr(p, ']');
        if (!close_bracket) continue;

        int hour = 0;
        if (close_bracket - p >= 13) {
            hour = (p[11] - '0') * 10 + (p[12] - '0');
        }

        p = close_bracket + 1;
        while (*p == ' ') p++;

        char level[MAX_STR] = "";
        int i = 0;
        while (*p && *p != ' ' && i < MAX_STR - 1) {
            level[i++] = *p++;
        }
        level[i] = '\0';

        while (*p == ' ') p++;

        char component[MAX_STR] = "";
        if (*p == '(') {
            p++;
            i = 0;
            while (*p && *p != ')' && i < MAX_STR - 1) {
                component[i++] = *p++;
            }
            component[i] = '\0';
            if (*p == ')') p++;
        }

        while (*p == ' ') p++;
        if (*p == '-') {
            p++;
            while (*p == ' ') p++;
        }

        char message[MAX_STR] = "";
        i = 0;
        while (*p && i < MAX_STR - 1) {
            message[i++] = *p++;
        }
        message[i] = '\0';

        strncpy(entries[count].level, level, MAX_STR - 1);
        entries[count].level[MAX_STR - 1] = '\0';
        strncpy(entries[count].component, component, MAX_STR - 1);
        entries[count].component[MAX_STR - 1] = '\0';
        strncpy(entries[count].message, message, MAX_STR - 1);
        entries[count].message[MAX_STR - 1] = '\0';
        entries[count].hour = hour;

        count++;
    }

    fclose(fp);

    printf("=== Log Analysis ===\n");
    printf("\n");

    printf("Entries by Level:\n");

    size_t alloc_sz = (count > 0 ? (size_t)count : 1) * sizeof(char *);
    char **levels = malloc(alloc_sz);
    int level_count = 0;
    for (int i = 0; i < count; i++) {
        int found = 0;
        for (int j = 0; j < level_count; j++) {
            if (strcmp(levels[j], entries[i].level) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            levels[level_count] = my_strdup(entries[i].level);
            level_count++;
        }
    }

    for (int i = 0; i < level_count - 1; i++) {
        for (int j = i + 1; j < level_count; j++) {
            if (strcmp(levels[i], levels[j]) > 0) {
                char *tmp = levels[i];
                levels[i] = levels[j];
                levels[j] = tmp;
            }
        }
    }

    for (int i = 0; i < level_count; i++) {
        int cnt = 0;
        for (int j = 0; j < count; j++) {
            if (strcmp(entries[j].level, levels[i]) == 0) cnt++;
        }
        printf("  %s: %d\n", levels[i], cnt);
    }

    printf("\n");

    printf("Component with Most Errors: ");

    char **error_components = malloc(alloc_sz);
    int ec_count = 0;
    for (int i = 0; i < count; i++) {
        if (strcmp(entries[i].level, "ERROR") == 0) {
            int found = 0;
            for (int j = 0; j < ec_count; j++) {
                if (strcmp(error_components[j], entries[i].component) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                error_components[ec_count] = my_strdup(entries[i].component);
                ec_count++;
            }
        }
    }

    int max_errors = 0;
    const char *most_error_component = "";
    for (int i = 0; i < ec_count; i++) {
        int cnt = 0;
        for (int j = 0; j < count; j++) {
            if (strcmp(entries[j].level, "ERROR") == 0 &&
                strcmp(entries[j].component, error_components[i]) == 0) {
                cnt++;
            }
        }
        if (cnt > max_errors) {
            max_errors = cnt;
            most_error_component = error_components[i];
        }
    }

    printf("%s (%d errors)\n", most_error_component, max_errors);

    printf("\n");

    printf("Unique Error Messages:\n");

    char **error_msgs = malloc(alloc_sz);
    int em_count = 0;
    for (int i = 0; i < count; i++) {
        if (strcmp(entries[i].level, "ERROR") == 0) {
            int found = 0;
            for (int j = 0; j < em_count; j++) {
                if (strcmp(error_msgs[j], entries[i].message) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                error_msgs[em_count] = my_strdup(entries[i].message);
                em_count++;
            }
        }
    }

    for (int i = 0; i < em_count - 1; i++) {
        for (int j = i + 1; j < em_count; j++) {
            if (strcmp(error_msgs[i], error_msgs[j]) > 0) {
                char *tmp = error_msgs[i];
                error_msgs[i] = error_msgs[j];
                error_msgs[j] = tmp;
            }
        }
    }

    for (int i = 0; i < em_count; i++) {
        printf("  - %s\n", error_msgs[i]);
    }

    printf("\n");

    int hour_counts[24] = {0};
    for (int i = 0; i < count; i++) {
        if (entries[i].hour >= 0 && entries[i].hour < 24) {
            hour_counts[entries[i].hour]++;
        }
    }

    int max_hour = 0;
    int max_hour_count = 0;
    for (int h = 0; h < 24; h++) {
        if (hour_counts[h] > max_hour_count) {
            max_hour_count = hour_counts[h];
            max_hour = h;
        }
    }

    printf("Busiest Hour: %02d:00 (%d entries)\n", max_hour, max_hour_count);

    free(entries);
    for (int i = 0; i < level_count; i++) free(levels[i]);
    free(levels);
    for (int i = 0; i < ec_count; i++) free(error_components[i]);
    free(error_components);
    for (int i = 0; i < em_count; i++) free(error_msgs[i]);
    free(error_msgs);

    return 0;
}
