import Foundation

let baseDir = "<tmp>"
let fm = FileManager.default
let baseURL = URL(fileURLWithPath: baseDir)

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var filesByExtension: [String: [FileInfo]] = [:]

let enumerator = fm.enumerator(at: baseURL,
                                includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
                                options: [],
                                errorHandler: { _, _ in true })

while let url = enumerator?.nextObject() as? URL {
    let values = try? url.resourceValues(forKeys: [.isRegularFileKey, .isSymbolicLinkKey])
    let isRegularFile = values?.isRegularFile ?? false
    let isSymlink = values?.isSymbolicLink ?? false

    guard isRegularFile && !isSymlink else { continue }

    guard let data = fm.contents(atPath: url.path) else { continue }

    let chars = data.count

    let lines: Int
    if data.isEmpty {
        lines = 0
    } else {
        var newlineCount = 0
        for byte in data where byte == 10 {
            newlineCount += 1
        }
        let lastByte = data[data.count - 1]
        lines = newlineCount + (lastByte != 10 ? 1 : 0)
    }

    let relativePath = url.path.replacingOccurrences(of: baseDir + "/", with: "")
    let extKey = "." + url.pathExtension

    let info = FileInfo(relativePath: relativePath, lines: lines, chars: chars)
    filesByExtension[extKey, default: []].append(info)
}

print("=== File Tree Analysis ===")
print("")

var totalFiles = 0
var totalLines = 0
var totalChars = 0

let sortedExtensions = filesByExtension.keys.sorted()

for ext in sortedExtensions {
    let fileInfos = filesByExtension[ext]!.sorted { $0.relativePath < $1.relativePath }
    let extFiles = fileInfos.count
    let extLines = fileInfos.reduce(0) { $0 + $1.lines }
    let extChars = fileInfos.reduce(0) { $0 + $1.chars }

    totalFiles += extFiles
    totalLines += extLines
    totalChars += extChars

    print("Extension: \(ext)")
    print("  Files: \(extFiles)")
    print("  Total Lines: \(extLines)")
    print("  Total Characters: \(extChars)")
    for info in fileInfos {
        print("    \(info.relativePath): \(info.lines) lines, \(info.chars) chars")
    }
}

print("")
print("Total: \(totalFiles) files, \(totalLines) lines, \(totalChars) characters")

