#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>

#define BASE_DIR "<tmp>"

typedef struct {
    char *relpath;
    char *ext;
    long lines;
    long chars;
} FileInfo;

typedef struct {
    FileInfo *items;
    int count;
    int capacity;
} FileList;

static void file_list_add(FileList *fl, char *relpath, char *ext, long lines, long chars) {
    if (fl->count == fl->capacity) {
        int newcap = fl->capacity == 0 ? 64 : fl->capacity * 2;
        fl->items = (FileInfo *)realloc(fl->items, newcap * sizeof(FileInfo));
        if (!fl->items) { perror("realloc"); exit(1); }
        fl->capacity = newcap;
    }
    fl->items[fl->count].relpath = relpath;
    fl->items[fl->count].ext = ext;
    fl->items[fl->count].lines = lines;
    fl->items[fl->count].chars = chars;
    fl->count++;
}

static char *get_extension(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (dot && dot != filename) {
        return strdup(dot);
    }
    return strdup("");
}

static void walk_dir(const char *abs_path, const char *rel_path, FileList *fl) {
    DIR *dir = opendir(abs_path);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char abs_entry[4096];
        snprintf(abs_entry, sizeof(abs_entry), "%s/%s", abs_path, entry->d_name);

        char rel_entry[4096];
        if (rel_path[0] == '\0') {
            snprintf(rel_entry, sizeof(rel_entry), "%s", entry->d_name);
        } else {
            snprintf(rel_entry, sizeof(rel_entry), "%s/%s", rel_path, entry->d_name);
        }

        struct stat st;
        if (lstat(abs_entry, &st) != 0) continue;

        if (S_ISLNK(st.st_mode)) continue;

        if (S_ISREG(st.st_mode)) {
            long chars = (long)st.st_size;
            long lines = 0;
            FILE *f = fopen(abs_entry, "rb");
            if (f) {
                int c;
                while ((c = fgetc(f)) != EOF) {
                    if (c == '\n') lines++;
                }
                fclose(f);
            }

            char *rel = strdup(rel_entry);
            char *ext = get_extension(entry->d_name);
            file_list_add(fl, rel, ext, lines, chars);
        } else if (S_ISDIR(st.st_mode)) {
            walk_dir(abs_entry, rel_entry, fl);
        }
    }
    closedir(dir);
}

static int compare_files(const void *a, const void *b) {
    const FileInfo *fa = (const FileInfo *)a;
    const FileInfo *fb = (const FileInfo *)b;
    int cmp = strcmp(fa->ext, fb->ext);
    if (cmp != 0) return cmp;
    return strcmp(fa->relpath, fb->relpath);
}

int main(void) {
    FileList fl;
    fl.items = NULL;
    fl.count = 0;
    fl.capacity = 0;

    walk_dir(BASE_DIR, "", &fl);

    if (fl.count > 1) {
        qsort(fl.items, fl.count, sizeof(FileInfo), compare_files);
    }

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long total_files = 0;
    long total_lines = 0;
    long total_chars = 0;

    int i = 0;
    while (i < fl.count) {
        const char *cur_ext = fl.items[i].ext;
        long ext_files = 0;
        long ext_lines = 0;
        long ext_chars = 0;

        int j = i;
        while (j < fl.count && strcmp(fl.items[j].ext, cur_ext) == 0) {
            ext_files++;
            ext_lines += fl.items[j].lines;
            ext_chars += fl.items[j].chars;
            j++;
        }

        printf("Extension: %s\n", cur_ext);
        printf("  Files: %ld\n", ext_files);
        printf("  Total Lines: %ld\n", ext_lines);
        printf("  Total Characters: %ld\n", ext_chars);
        for (int k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n", fl.items[k].relpath, fl.items[k].lines, fl.items[k].chars);
