static void *xmalloc(size_t n) {
    void *p = malloc(n);
    if (!p) { fprintf(stderr, "malloc failed\n"); exit(1); }
    return p;
}

static void *xrealloc(void *p, size_t n) {
    void *q = realloc(p, n);
    if (!q) { fprintf(stderr, "realloc failed\n"); exit(1); }
    return q;
}

static void skip_ws(const char **s) {
    while (**s == ' ' || **s == '\t' || **s == '\n' || **s == '\r') (*s)++;
}

static int parse_string(const char **s, char *out, int maxlen) {
    if (**s != '"') return -1;
    (*s)++;
    int i = 0;
    while (**s && **s != '"') {
        if (**s == '\\') {
            (*s)++;
            if (**s == '"') out[i++] = '"';
            else if (**s == '\\') out[i++] = '\\';
            else if (**s == '/') out[i++] = '/';
            else if (**s == 'n') out[i++] = '\n';
            else if (**s == 't') out[i++] = '\t';
            else if (**s == 'r') out[i++] = '\r';
            else if (**s == 'b') out[i++] = '\b';
            else if (**s == 'f') out[i++] = '\f';
            else if (**s == 'u') {
                /* skip 4 hex digits, store '?' */
                for (int k = 0; k < 4 && **s; k++) (*s)++;
                out[i++] = '?';
            } else out[i++] = **s;
        } else {
            out[i++] = **s;
            (*s)++;
        }
        if (i >= maxlen - 1) break;
    }
    if (**s == '"') (*s)++;
    out[i] = '\0';
    return i;
}

static long long parse_number(const char **s) {
    skip_ws(s);
    const char *p = *s;
    int neg = 0;
    if (*p == '-') { neg = 1; p++; }
