    (*s)++;
    int i = 0;
    while (**s && **s != '"') {
        if (**s == '\\') {
            (*s)++;
            if (**s == '"') out[i++] = '"';
            else if (**s == '\\') out[i++] = '\\';
            else if (**s == '/') out[i++] = '/';
            else if (**s == 'n') out[i++] = '\n';
            else if (**s == 't') out[i++] = '\t';
            else if (**s == 'r') out[i++] = '\r';
            else if (**s == 'b') out[i++] = '\b';
            else if (**s == 'f') out[i++] = '\f';
            else if (**s == 'u') {
                for (int k = 0; k < 4 && **s; k++) (*s)++;
                out[i++] = '?';
            } else out[i++] = **s;
        } else {
            out[i++] = **s;
            (*s)++;
        }
        if (i >= maxlen - 1) break;
    }
    if (**s == '"') (*s)++;
    out[i] = '\0';
    return i;
}

static long long parse_number(const char **s) {
    skip_ws(s);
    const char *p = *s;
    int neg = 0;
    if (*p == '-') { neg = 1; p++; }
    long long val = 0;
    while (*p >= '0' && *p <= '9') { val = val * 10 + (*p - '0'); p++; }
    if (*p == '.') {
        p++;
        while (*p >= '0' && *p <= '9') p++;
    }
    if (*p == 'e' || *p == 'E') {
        p++;
        if (*p == '+' || *p == '-') p++;
        while (*p >= '0' && *p <= '9') p++;
    }
    *s = p;
    return neg ? -val : val;
}

static int find_node_index(char **nodes, int n, const char *name) {
    for (int i = 0; i < n; i++) {
        if (strcmp(nodes[i], name) == 0) return i;
    }
    return -1;
}

int main(void) {
    FILE *f = fopen(FILE_PATH, "r");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = xmalloc((size_t)fsize + 1);
    if (fread(buf, 1, (size_t)fsize, f) != (size_t)fsize) { fclose(f); free(buf); return 1; }
    buf[fsize] = '\0';
    fclose(f);

    /* Parse nodes */
    const char *p = buf;
    const char *nodes_key = strstr(p, "\"nodes\"");
    if (!nodes_key) { fprintf(stderr, "nodes not found\n"); free(buf); return 1; }
    p = nodes_key + 7;
    skip_ws(&p);
    if (*p != ':') { fprintf(stderr, "expected : after nodes\n"); free(buf); return 1; }
    p++;
    skip_ws(&p);
    if (*p != '[') { fprintf(stderr, "expected [ for nodes\n"); free(buf); return 1; }
    p++;

    char **nodes = NULL;
    int num_nodes = 0, cap_nodes = 0;
    while (1) {
        skip_ws(&p);
        if (*p == ']') { p++; break; }
        if (*p == ',') { p++; continue; }
        if (*p == '\0') break;
        char name[256];
        if (parse_string(&p, name, 256) < 0) { fprintf(stderr, "parse node string failed\n"); free(buf); return 1; }
        if (num_nodes == cap_nodes) {
            cap_nodes = cap_nodes ? cap_nodes * 2 : 64;
            nodes = xrealloc(nodes, (size_t)cap_nodes * sizeof(char *));
        }
        nodes[num_nodes] = strdup(name);
        num_nodes++;
    }

    /* Parse edges */
    const char *edges_key = strstr(buf, "\"edges\"");
    if (!edges_key) { fprintf(stderr, "edges not found\n"); free(buf); return 1; }
    p = edges_key + 7;
    skip_ws(&p);
    if (*p != ':') { fprintf(stderr, "expected : after edges\n"); free(buf); return 1; }
    p++;
    skip_ws(&p);
    if (*p != '[') { fprintf(stderr, "expected [ for edges\n"); free(buf); return 1; }
    p++;

    int *e_from = NULL, *e_to = NULL;
    long long *e_weight = NULL;
    int num_edges = 0, cap_edges = 0;

    while (1) {
        skip_ws(&p);
        if (*p == ']') { p++; break; }
        if (*p == ',') { p++; continue; }
        if (*p == '\0') break;
        if (*p != '{') { fprintf(stderr, "expected { in edges\n"); free(buf); return 1; }
        p++;

        char from_str[256] = "", to_str[256] = "";
        long long weight = 0;
        int has_from = 0, has_to = 0, has_weight = 0;

        while (*p && *p != '}') {
            skip_ws(&p);
            if (*p == '}') break;
            if (*p == ',') { p++; continue; }

            /* Must be a key */
            if (*p != '"') { p++; continue; }

            char key[64];
            if (parse_string(&p, key, 64) < 0) { p++; continue; }
            skip_ws(&p);
            if (*p == ':') { p++; skip_ws(&p); }

            if (strcmp(key, "from") == 0) {
                if (parse_string(&p, from_str, 256) >= 0) has_from = 1;
            } else if (strcmp(key, "to") == 0) {
                if (parse_string(&p, to_str, 256) >= 0) has_to = 1;
            } else if (strcmp(key, "weight") == 0) {
                weight = parse_number(&p);
                has_weight = 1;
            } else {
                /* skip unknown value */
                if (*p == '"') {
                    char tmp[256];
                    parse_string(&p, tmp, 256);
                } else {
                    parse_number(&p);
                }
            }
        }
        if (*p == '}') p++;

        if (has_from && has_to && has_weight) {
            int fi = find_node_index(nodes, num_nodes, from_str);
            int ti = find_node_index(nodes, num_nodes, to_str);
            if (fi >= 0 && ti >= 0) {
                if (num_edges == cap_edges) {
                    cap_edges = cap_edges ? cap_edges * 2 : 128;
                    e_from = xrealloc(e_from, (size_t)cap_edges * sizeof(int));
                    e_to = xrealloc(e_to, (size_t)cap_edges * sizeof(int));
                    e_weight = xrealloc(e_weight, (size_t)cap_edges * sizeof(long long));
                }
                e_from[num_edges] = fi;
                e_to[num_edges] = ti;
                e_weight[num_edges] = weight;
                num_edges++;
            }
        }
    }

    free(buf);

    /* Build adjacency list */
    AdjNode **adj = xmalloc((size_t)num_nodes * sizeof(AdjNode *));
    for (int i = 0; i < num_nodes; i++) adj[i] = NULL;

    for (int i = 0; i < num_edges; i++) {
        int u = e_from[i], v = e_to[i];
        long long w = e_weight[i];
        AdjNode *n1 = xmalloc(sizeof(AdjNode));
        n1->to = v; n1->weight = w; n1->next = adj[u]; adj[u] = n1;
        AdjNode *n2 = xmalloc(sizeof(AdjNode));
        n2->to = u; n2->weight = w; n2->next = adj[v]; adj[v] = n2;
    }

    free(e_from);
    free(e_to);
    free(e_weight);

    /* Find source node "A" */
    int src = find_node_index(nodes, num_nodes, "A");
    if (src < 0) { fprintf(stderr, "node A not found\n"); return 1; }

    /* Dijkstra's algorithm */
    long long *dist = xmalloc((size_t)num_nodes * sizeof(long long));
    int *visited = xmalloc((size_t)num_nodes * sizeof(int));
    for (int i = 0; i < num_nodes; i++) {
        dist[i] = LLONG_MAX;
        visited[i] = 0;
    }
    dist[src] = 0;

    for (int iter = 0; iter < num_nodes; iter++) {
        int u = -1;
        long long best = LLONG_MAX;
        for (int i = 0; i < num_nodes; i++) {
            if (!visited[i] && dist[i] < best) {
                best = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;
        AdjNode *e = adj[u];
        while (e) {
            if (!visited[e->to] && dist[u] + e->weight < dist[e->to]) {
                dist[e->to] = dist[u] + e->weight;
            }
            e = e->next;
        }
    }

    /* Sort node indices alphabetically */
    int *order = xmalloc((size_t)num_nodes * sizeof(int));
    for (int i = 0; i < num_nodes; i++) order[i] = i;
    for (int i = 0; i < num_nodes; i++) {
        int min_i = i;
        for (int j = i + 1; j < num_nodes; j++) {
            if (strcmp(nodes[order[j]], nodes[order[min_i]]) < 0) min_i = j;
        }
        int tmp = order[i]; order[i] = order[min_i]; order[min_i] = tmp;
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n");
    printf("\n");
    for (int i = 0; i < num_nodes; i++) {
        int idx = order[i];
        if (dist[idx] == LLONG_MAX) {
            printf("A -> %s: unreachable\n", nodes[idx]);
        } else {
            printf("A -> %s: %lld\n", nodes[idx], dist[idx]);
        }
    }

    /* Cleanup */
    for (int i = 0; i < num_nodes; i++) {
        AdjNode *e = adj[i];
        while (e) { AdjNode *nxt = e->next; free(e); e = nxt; }
        free(nodes[i]);
    }
    free(adj);
    free(nodes);
    free(dist);
    free(visited);
    free(order);

    return 0;
}

if (*p == ':') { p++; skip_ws(&p); }
